export {SPATIAL_SELECTION_OWNER_ID,SPATIAL_SELECTION_CONTRACT,SPATIAL_NEIGHBOR_POLICY,SPATIAL_SELECTION_SUBCONTRACTS,SpatialSelectionNavigationKernel,createSpatialProjectionDescriptor} from './spatial/selection-kernel.js';
